<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityActionRepository{public function __construct(private ?PDO $pdo=null){$this->pdo=$this->pdo??\App\Core\Database::connection();} public function create($sid,$r,$tid,$a,$q){$this->pdo->prepare('INSERT INTO liquidity_team_actions (session_id,round_number,team_id,action_type,quantity) VALUES (?,?,?,?,?)')->execute([$sid,$r,$tid,$a,$q]);} public function hasTeamActed($sid,$r,$tid){$s=$this->pdo->prepare('SELECT COUNT(*) FROM liquidity_team_actions WHERE session_id=? AND round_number=? AND team_id=?');$s->execute([$sid,$r,$tid]);return (int)$s->fetchColumn()>0;} public function getBySessionAndRound($sid,$r){$s=$this->pdo->prepare('SELECT * FROM liquidity_team_actions WHERE session_id=? AND round_number=?');$s->execute([$sid,$r]);return $s->fetchAll();}}
